    "difficulty": "Média",
    "statement": "Leia o capítulo CXI, “O muro”, do romance Memórias póstumas de Brás Cubas, de Machado de Assis, para responder às questões de 05 a 08.\n\nNão sendo meu costume dissimular ou esconder nada, contarei nesta página o caso do muro. Eles estavam prestes a embarcar. Entrando em casa de D. Plácida, vi um papelinho dobrado sobre a mesa; era um bilhete de Virgília; dizia que me esperava à noite, na chácara, sem falta. E concluía: “O muro é baixo do lado do beco”.\n\nFiz um gesto de desagrado. A carta pareceu-me descomunalmente audaciosa, mal pensada e até ridícula. Não era só convidar o escândalo, era convidá-lo de parceria com a risota. Imaginei-me a saltar o muro, embora baixo e do lado do beco; e, quando ia a galgá-lo, via-me agarrado por um pedestre de polícia, que me levava ao corpo da guarda. O muro é baixo! E que tinha que fosse baixo? Naturalmente Virgília não soube o que fez; era possível que já estivesse arrependida. Olhei para o papel, um pedaço de papel amarrotado, mas inflexível. Tive comichões de o rasgar, em trinta mil pedaços, e atirá-los ao vento, como o último despojo da minha aven tura; mas recuei a tempo; o amor-próprio, o vexame da fuga, a ideia do medo... Não havia remédio senão ir.\n\n— Diga-lhe que vou. — Aonde? perguntou D. Plácida. — Onde ela disse que me espera. — Não me disse nada. — Neste papel. D. Plácida arregalou os olhos: — Mas esse papel, achei-o hoje de manhã, nesta sua gaveta, e pensei que...\n\nTive uma sensação esquisita. Reli o papel, mirei-o, remirei-o; era, na verdade, um antigo bilhete de Virgília, recebido no começo dos nossos amores, uma certa entrevista na chácara, que me levou efetivamente a saltar o muro, um muro baixo e discreto. Guardei o papel e... Tive uma sensação esquisita.\n\n(Memórias póstumas de Brás Cubas, 2001.)\n\nLogo na frase inicial do seu relato, o narrador caracteriza-se como",
