    "statement": "Leia o texto para responder às questões de 09 a 12.\n\n¿Qué es tsundoku y qué tiene que ver con los libros? Confieso que la palabra tsundoku me representa a la perfección. A menudo me siento afortunado por tener tantos libros nuevos para leer, pero luego pienso en el poco tiempo, espacio e inversión económica que hay detrás de esta acumulación libresca. Supongo que ya sabrás o habrás imaginado lo que significa este vocablo. De todas formas, trataré de darte una explicación más clara.\n\nTsundoku es un término japonés que se refiere al acto de comprar un libro y dejarlo sin leer junto con otros libros no leídos. Dicha palabra se podría asemejar en español a bibliomanía: propensión exagerada a acumular libros. Bien es cierto que el término castellano no hace referencia expresa a la no lectura de dichos libros, aunque se puede intuir de este trastorno obsesivo-compulsivo de coleccionar libros.\n\nEl idioma japonés dispone de una extensa cantidad de palabras para referirse a cada una de las cosas cotidianas que les rodean. Uno de esos vocablos es tsundoku, que nace de modificar la expresión tsunde oku cuyo significado es «dejar que algo se acumule». La parte final oku lleva una d puesto que doku significa leer.\n\n(www.julianmarquina.es, 09.08.2022. Adaptado.)\n\nSegún el autor, a diferencia de “bibliomanía”, el significado del término “tsundoku” conlleva la",
