    "statement": "Leia o excerto sobre o Tratado de Santo Ildefonso.\n\nAs novas partidas demarcadoras obtiveram êxito em atingir consensos sobre a maioria dos pontos pelos quais devia se estabelecer a linha demarcatória. Foram décadas de tentativas infrutíferas de negociação pelas partes, porém, dessa vez a diferença estava no fato de que a falta de concordância entre as partidas de ambas as nações [Portugal e Espanha] não serviu de pretexto para novos confrontos militares.\n\n(Fernando Camargo. “A pendenga interminável: as demarcações do\n\nTratado de Santo Ildefonso”. Anais da XXIII Reunião da\n\nSociedade Brasileira de Pesquisa Histórica, 2003. Adaptado.)\n\nO Tratado de Santo Ildefonso (1777) reafirmou pontos do Tratado de Madri (1750) e trouxe novas questões, que geraram",
