    "statement": "Leia um trecho da obra Infância, de Graciliano Ramos, para responder às questões de 01 a 04.\n\nMergulhei numa comprida manhã de inverno. O açude apojado, a roça verde, amarela e vermelha, os caminhos estreitos mudados em riachos, ficaram-me na alma. Depois veio a seca. Árvores pelaram-se, bichos morreram, o sol cresceu, bebeu as águas, e ventos mornos espalharam na terra queimada uma poeira cinzenta. Olhando-me por dentro, percebo com desgosto a segunda paisagem. Devastação, calcinação. Nesta vida lenta sinto-me coagido entre duas situações contraditórias — uma longa noite, um dia imenso e enervante, favorável à modorra. Frio e calor, trevas densas e claridades ofuscantes.\n\nNaquele tempo a escuridão se ia dissipando, vagarosa. Acordei, reuni pedaços de pessoas e de coisas, pedaços de mim mesmo que boiavam no passado confuso, articulei tudo, criei o meu pequeno mundo incongruente. Às vezes as peças se deslocavam — e surgiam estranhas mudanças. Os objetos se tornavam irreconhecíveis, e a humanidade, feita de indivíduos que me atormentavam e indivíduos que não me atormentavam, perdia os característicos.\n\nBem e mal ainda não existiam, faltava razão para que nos afligissem com pancadas e gritos. Contudo as pancadas e os gritos figuravam na ordem dos acontecimentos, partiam sempre de seres determinados, como a chuva e o sol vinham do céu. E o céu era terrível, e os donos da casa eram fortes. Ora, sucedia que a minha mãe abrandava de repente e meu pai, silencioso, explosivo, resolvia contar-me histórias. Admirava-me, aceitava a lei nova, ingênuo, admitia que a natureza se houvesse modificado. Fechava-se o doce parêntese — e isso me desorientava.\n\n(Infância, 2020.)\n\nO Dicionário Eletrônico Houaiss da Língua Portuguesa define “antítese” como “figura pela qual se opõem, numa mesma frase, duas palavras ou dois pensamentos de sentido contrário”, a exemplo do que se verifica em:",
