    "subject": "Espanhol",
    "detail": "Espanhol — UEA 2022 Acompanhamento III",
    "difficulty": "Difícil",
    "statement": "Leia o texto para responder às questões de 09 a 12.\n\n¿Qué es la gastronomía inmersiva?\n\nLa gastronomía inmersiva, cocina inmersiva o gastronomía hecha espectáculo, es la forma idónea de atraer comensales a tu restaurante, y es una de las tendencias en hostelería más populares para este año 2022. Algunos ejemplos de gastronomía inmersiva son todos aquellos restaurantes que permiten a los clientes formar parte en la preparación de los platos que ellos mismos han elegido en el menú. Otro ejemplo son los restaurantes que invitan a vivir una experiencia culinaria haciendo uso de todos los sentidos. También los restaurantes que usan imágenes, estímulos sonoros, aromáticos, visuales, táctiles y gustativos para hacer sentir que se está viviendo una experiencia que está más allá del hecho de comer. Para ello, los restaurantes se presentan acordes a la experiencia. A través de luz tenue y música adecuada para aprovechar de esta forma el poder de los sentidos, lo que hace de la cocina inmersiva una experiencia gastronómica sin igual.\n\nNo podemos hablar de gastronomía inmersiva sin mencionar la importancia que tiene la tecnología para poder llevarla a cabo. La tecnología inmersiva abre enormes posibilidades para activar los sentidos en el mundo culinario y la hostelería. Esta cocina, impulsada por tecnología 3D, brinda a los comensales una experiencia integral y recibe recomendaciones adaptadas a sus gustos y preferencias. Gracias al uso de las nuevas tecnologías, el cliente puede percibir el brillo y los matices de los exquisitos platos que va a consumir.\n\nAdemás, esta tecnología no solo ayuda en la experiencia gastronómica de los platos, sino que también permite reconocer a los comensales cuando llegan al local. Puede darles la bienvenida y permitirles elegir lo que verán en su mesa, de forma multitáctil e interactiva. El contenido audiovisual potencia los aspectos lúdicos para brindar a los clientes una experiencia culinaria inolvidable, como puede ser el reconocimiento facial o los mapas de calor.\n\n(“Gastronomia inmersiva en hostelería”.\n\nhttps://controliza.com, 29.04.2022. Adaptado.)\n\nEn el primer párrafo el autor se ha preocupado fundamentalmente de",
