    "statement": "O Parque Nacional do Jaú, administrado pelo Instituto Chico Mendes para Conservação da Biodiversidade (ICMBio) possui, aproximadamente, 2,4 milhões de hectares, é uma importante amostra dos ecossistemas amazônicos e está localizado entre os municípios de Novo Airão e Barcelos, ao norte do Estado do Amazonas. O parque está vinculado ao Projeto de Parques e Reservas do Ibama (Projeto Corredores Ecológicos), criado para unir diferentes espaços protegidos e unidades de conservação da região biogeográfica em um imenso corredor verde.\n\n(http://portal.iphan.gov.br. Adaptado.)\n\nCorredores ecológicos, como o Parque Nacional do Jaú, são uma estratégia para",
